package cl.cappucare.backend;
import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.dao.DuplicateKeyException;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/medicamentos") public class MedicamentoController {
 private final JdbcTemplate db; public MedicamentoController(JdbcTemplate db){this.db=db;}
 @GetMapping public Map<String,Object> listar(){return Map.of("medicamentos",db.queryForList("SELECT * FROM medicamentos"));}
 @GetMapping("/codigo/{codigo}") public Map<String,Object> buscar(@PathVariable String codigo){var lista=db.queryForList("SELECT * FROM medicamentos WHERE codigo=?",codigo.trim());if(lista.isEmpty())throw new ApiError(HttpStatus.NOT_FOUND,"Medicamento no encontrado");return Map.of("medicamento",lista.get(0));}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> crear(@RequestBody Map<String,Object> m){validar(m,true);String c=texto(m,"codigo").trim();try{db.update("INSERT INTO medicamentos(codigo,nombre,principioActivo,concentracion,laboratorio,stock) VALUES(?,?,?,?,?,?)",c,texto(m,"nombre").trim(),texto(m,"principioActivo"),texto(m,"concentracion"),texto(m,"laboratorio"),stock(m));}catch(DuplicateKeyException ex){throw new ApiError(HttpStatus.CONFLICT,"Este código ya está registrado");}return Map.of("mensaje","Medicamento registrado correctamente","medicamento",buscar(c).get("medicamento"));}
 @PutMapping("/{codigo}") public Map<String,Object> editar(@PathVariable String codigo,@RequestBody Map<String,Object> m){validar(m,false);int n=db.update("UPDATE medicamentos SET nombre=?,principioActivo=?,concentracion=?,laboratorio=?,stock=? WHERE codigo=?",texto(m,"nombre").trim(),texto(m,"principioActivo"),texto(m,"concentracion"),texto(m,"laboratorio"),stock(m),codigo.trim());if(n==0)throw new ApiError(HttpStatus.NOT_FOUND,"Medicamento no encontrado");return Map.of("mensaje","Medicamento actualizado correctamente","medicamento",buscar(codigo).get("medicamento"));}
 @DeleteMapping("/{codigo}") public Map<String,Object> borrar(@PathVariable String codigo){if(db.update("DELETE FROM medicamentos WHERE codigo=?",codigo.trim())==0)throw new ApiError(HttpStatus.NOT_FOUND,"Medicamento no encontrado");return Map.of("mensaje","Medicamento eliminado correctamente","codigoEliminado",codigo.trim());}
 private static String texto(Map<String,Object> m,String k){Object v=m.get(k);return v instanceof String?(String)v:"";}
 private static int stock(Map<String,Object> m){Object n=m.getOrDefault("stock",0);if(!(n instanceof Integer)||((Integer)n)<0)throw new ApiError(HttpStatus.BAD_REQUEST,"El stock debe ser entero y no negativo");return (Integer)n;}
 private static void validar(Map<String,Object> m,boolean crear){if((crear&&texto(m,"codigo").isBlank())||texto(m,"nombre").isBlank())throw new ApiError(HttpStatus.BAD_REQUEST,"El código y el nombre son obligatorios");stock(m);}
}
